import React, { useState } from 'react';
import PropertyPage from './pages/PropertyPage';
import RenterPage from './pages/RenterPage';
import ReviewList from './pages/ReviewList';
import LeasingOfficeList from './pages/LeasingOfficeList';
import LeaseApplicationList from './pages/LeaseApplicationList';

function App() {
  const [currentPage, setCurrentPage] = useState('property');

  const renderPage = () => {
    switch (currentPage) {
      case 'properties':
        return <PropertyPage />;
      case 'renter':
        return <RenterPage />;
      case 'review':
        return <ReviewList />;
      case 'leasingOffice':
        return <LeasingOfficeList />;
      case 'leaseApplication':
        return <LeaseApplicationList />;
      default:
        return <PropertyPage />;
    }
  };

  return (
    <div>
      <nav>
        <button onClick={() => setCurrentPage('property')}>Properties</button>
        <button onClick={() => setCurrentPage('renter')}>Renters</button>
        <button onClick={() => setCurrentPage('review')}>Reviews</button>
        <button onClick={() => setCurrentPage('leasingOffice')}>Leasing Offices</button>
        <button onClick={() => setCurrentPage('leaseApplication')}>Lease Applications</button>
      </nav>
      {renderPage()}
    </div>
  );
}

export default App;
